    int32_t field_length;
    int32_t item_count;
    MOVFragmentIndex *index;
    int64_t size = avio_rb32(f);
    uint32_t tag = avio_rl32(f);

    if (tag != MKTAG('t', 'f', 'r', 'a')) {
        return AVERROR_INVALIDDATA;
    }

    version = avio_r8(f);
    track_id = avio_rb32(f);
    field_length = avio_r8(f);
    avio_skip(f, 3); // reserved
    item_count = avio_rb32(f);

