int read_tfra_box(MOVContext *mov, AVIOContext *f) {
    uint32_t box_type;
    int64_t box_size;

    // Check if the box type is 'tfra'
    box_type = avio_rl32(f);
    if (box_type != MKTAG('t', 'f', 'r', 'a')) {
        avio_seek(f, -4, SEEK_CUR); // Rewind the 4 bytes read
        return AVERROR_INVALIDDATA;
    }

    // Read box size
    box_size = avio_rb32(f);

    // Skip box size (we'll read until the end later)
    avio_seek(f, -8, SEEK_CUR); // Rewind 8 bytes (box type + size)
    mov->frag_index = av_mallocz(sizeof(MOVFragmentIndex));
    if (!mov->frag_index)
        return AVERROR(ENOMEM);

    // Resize the fragment index data array if needed
    mov->frag_index->data = av_realloc_array(mov->frag_index->data, mov->frag_index->count + 1, sizeof(*mov->frag_index->data));
    if (!mov->frag_index->data) {
        av_free(mov->frag_index);
        mov->frag_index = NULL;
        return AVERROR(ENOMEM);
    }

    // Read version, track ID, field length, and item count
    mov->frag_index->version = avio_r8(f);
    mov->frag_index->track_id = avio_rb32(f);
    mov->frag_index->field_length = avio_r8(f);
    mov->frag_index->item_count = avio_rb32(f);

    for (int i = 0; i < mov->frag_index->item_count; i++) {
        int64_t time;
        int64_t offset;

        // Read time and offset, handling different versions
        time = avio_rb64(f);
        offset = avio_rb64(f);

        // Store the data in the fragment index
        mov->frag_index->data[mov->frag_index->count].time = time;
        mov->frag_index->data[mov->frag_index->count].offset = offset;
        mov->frag_index->count++;
    }

    // Seek to the end of the 'tfra' box
    avio_seek(f, box_size, SEEK_CUR);
    return 0;
}

int read_tfra_box(MOVContext *mov, AVIOContext *f) {
    uint32_t box_type;
    int64_t box_size;

    box_type = avio_rl32(f);
    if (box_type != MKTAG('t', 'f', 'r', 'a')) {
        avio_seek(f, -4, SEEK_CUR);
        return AVERROR_INVALIDDATA;
    }

    box_size = avio_rb64(f);
    if (box_size < 0) {
        return AVERROR_INVALIDDATA;
    }

    uint8_t version = avio_r8(f);
    uint32_t track_id = avio_rl32(f);
    uint8_t field_length = avio_r8(f);
    uint32_t item_count = avio_rl32(f);

    // Allocate a new fragment index structure
    MOVFragmentIndex *index = av_mallocz(sizeof(*index));
    if (!index) {
        return AVERROR(ENOMEM);
    }

    index->track_id = track_id;
    index->item_count = item_count;
    index->time_offset = av_mallocz_array(item_count, sizeof(*index->time_offset));
    if (!index->time_offset) {
        av_freep(&index);
        return AVERROR(ENOMEM);
    }

    for (uint32_t i = 0; i < item_count; i++) {
        int64_t time;
        if (version == 0) {
            time = avio_rb32(f);
        } else {
            time = avio_rb64(f);
        }

        int64_t offset = avio_rb64(f);
        index->time_offset[i].time = time;
        index->time_offset[i].offset = offset;
    }

    // Resize the fragment index data array and add the new index
    if (mov->fragment_index_count >= mov->fragment_index_capacity) {
        mov->fragment_index_capacity += 16;
        mov->fragment_index = av_realloc_array(mov->fragment_index, mov->fragment_index_capacity, sizeof(*mov->fragment_index));
        if (!mov->fragment_index) {
            av_freep(&index->time_offset);
            av_freep(&index);
            return AVERROR(ENOMEM);
        }
    }

    mov->fragment_index[mov->fragment_index_count++] = index;

    avio_seek(f, box_size, SEEK_SET);

    return 0;
}

